package com.example.doctoolkit.ui;
import android.app.*; import android.content.*; import android.os.*; import android.view.*; import android.widget.*; import androidx.recyclerview.widget.*; import com.example.doctoolkit.R; import com.example.doctoolkit.data.*; import java.text.*; import java.util.*;
public class HistoryActivity extends Activity{ public void onCreate(Bundle b){super.onCreate(b); setContentView(R.layout.activity_history); RecyclerView rv=findViewById(R.id.historyList); rv.setLayoutManager(new LinearLayoutManager(this)); new Thread(()->{List<HistoryItem> items=AppDatabase.get(this).historyDao().lastTen(); runOnUiThread(()->rv.setAdapter(new Adapter(items)));}).start();} class Adapter extends RecyclerView.Adapter<VH>{List<HistoryItem> items; Adapter(List<HistoryItem> i){items=i;} public VH onCreateViewHolder(ViewGroup p,int v){TextView t=new TextView(p.getContext()); t.setPadding(16,16,16,16); return new VH(t);} public void onBindViewHolder(VH h,int pos){HistoryItem it=items.get(pos); ((TextView)h.itemView).setText(it.tool+" • "+it.sourceName+"\n"+DateFormat.getDateTimeInstance().format(new Date(it.createdAt))+"\nTap to re-open"); h.itemView.setOnClickListener(v->startActivity(new Intent(HistoryActivity.this,ResultActivity.class).putExtra("path",it.outputPath)));} public int getItemCount(){return items.size();}} static class VH extends RecyclerView.ViewHolder{VH(View v){super(v);}}}
